        msgStore.createIndex('conversationId', 'conversationId', { unique: false });
        msgStore.createIndex('createdAt', 'createdAt', { unique: false });
      }

      // Knowledge Documents
      if (!db.objectStoreNames.contains('documents')) {
        db.createObjectStore('documents', { keyPath: 'id' });
